def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0]); fg=grid[0][0]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    left=all(grid[r][0]==fg for r in range(h)); top=all(v==fg for v in grid[0])
    for k in range(min(h,w)):
        r=k if top else h-1-k; c=k if left else w-1-k
        out[r][c]=8 if k<2 else bg
        if k:
            arm=fg if k==1 else 8
            if left: cols=range(k+1,w)
            else: cols=range(0,w-k-1)
            for cc in cols: out[r][cc]=arm
            if top: rows=range(k+1,h)
            else: rows=range(0,h-k-1)
            for rr in rows: out[rr][c]=arm
    return out
